CREATE TABLE qc_versions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, version_id TEXT NOT NULL, parent_id TEXT REFERENCES qc_versions(id), source_job_id TEXT NOT NULL REFERENCES jobs(id), engine_id TEXT NOT NULL REFERENCES engine_releases(id), status TEXT NOT NULL CHECK(status IN ('PENDING','FAILED','USER_ACTION_REQUIRED','PASSED')), packet_json TEXT NOT NULL, packet_sha256 TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES app_users(id), created_at TEXT NOT NULL, FOREIGN KEY(version_id,project_id) REFERENCES project_versions(id,project_id));
CREATE TABLE release_acceptances (id TEXT PRIMARY KEY, engine_id TEXT NOT NULL REFERENCES engine_releases(id), kind TEXT NOT NULL CHECK(kind IN ('CANONICAL_RUNTIME','POSTGRESQL')), lock_sha256 TEXT NOT NULL, evidence_json TEXT NOT NULL, created_at TEXT NOT NULL);
